from pathlib import Path
base=Path('browser-inventory29-round-8.js').read_text(encoding='utf-8-sig');base=base[:base.index('await move(1,520);')]
code=base+'''await move(0,520);await use(0);await bagItem(0,'bomb');await wait(2600);const dead=await state();if(!dead.failed||dead.heroes[0].hp!==0)throw Error('Missing lethal bomb damage');if(!await page.locator('#death').isVisible())throw Error('Death overlay hidden');await page.screenshot({path:'output/playwright/inventory29-death.png'});await page.locator('#retry-death').click();await wait(300);if((await state()).failed||(await state()).heroes.some(h=>h.hp!==3))throw Error('Retry did not reset health');
await page.setViewportSize({width:390,height:844});await page.locator('#bag').click();await wait(200);let bounds=await page.locator('#inventory-dialog').boundingBox();if(bounds.x<0||bounds.x+bounds.width>391)throw Error('Bag overflows portrait');if(await page.locator('[data-slot]').count()!==4)throw Error('Missing slots');await page.screenshot({path:'output/playwright/inventory29-mobile-bag.png'});await page.locator('#close-inventory').click();await page.locator('#fullscreen').click({trial:true});await page.setViewportSize({width:320,height:568});await page.locator('#bag').click();await wait(200);bounds=await page.locator('#inventory-dialog').boundingBox();if(bounds.x<0||bounds.x+bounds.width>321)throw Error('Bag overflows small phone');await page.locator('#use-item').click({trial:true}).catch(()=>{});await page.screenshot({path:'output/playwright/inventory29-small-bag.png'});await page.locator('#close-inventory').click();await page.setViewportSize({width:844,height:390});await page.locator('#bag').click();await wait(200);await page.screenshot({path:'output/playwright/inventory29-landscape-bag.png'});await page.locator('#close-inventory').click();return {death:dead.heroes.map(h=>h.hp),retry:'healthy',mobile:'390x844,320x568,844x390'};
}'''
Path('browser-inventory29-death-mobile.js').write_text(code,encoding='utf-8')
